import math

def error_rate(c: float, p: float, n: int) -> float:
    x = p
    for _ in range(n):
        x = c * x * x
    return x

def error_rate_closed_form(c: float, p: float, n: int) -> float:
    return (1.0 / c) * (c * p) ** (2 ** n)

def main() -> None:
    c, p = 100.0, 0.005  # below threshold: c*p = 0.5
    for n in range(7):
        a = error_rate(c, p, n)
        b = error_rate_closed_form(c, p, n)
        print(n, a, b, math.isclose(a, b, rel_tol=1e-9, abs_tol=1e-300))

if __name__ == "__main__":
    main()

def error_rate(c: float, p: float, n: int) -> float:
    x = p
    for _ in range(n):
        x = c * x * x
    return x

def classify(c: float, p: float) -> str:
    q0 = c * p
    if q0 < 1.0:
        return "below threshold -> 0"
    if q0 == 1.0:
        return "at threshold -> 1/c"
    return "above threshold -> +inf"

def main() -> None:
    c = 100.0
    for p in (0.005, 0.010, 0.020):
        print(f"p={p}  {classify(c, p)}")
        for n in range(6):
            print("   ", n, error_rate(c, p, n))

if __name__ == "__main__":
    main()

from typing import Iterable

def transversal_is_universal(transversal_group: Iterable[int],
                             ambient_is_infinite: bool) -> bool:
    transversal = set(transversal_group)
    if ambient_is_infinite:
        return False
    return True

def main() -> None:
    transversal = list(range(24))  # 24 single-qubit Cliffords, say
    print("|T| =", len(transversal))
    print("universal?", transversal_is_universal(transversal, ambient_is_infinite=True))

if __name__ == "__main__":
    main()

