import math

def levels_for_target(c: float, p: float, eps: float) -> int:
    q0 = c * p
    if not (0.0 <= q0 < 1.0):
        raise ValueError("requires 0 <= c*p < 1 (below threshold)")
    target = c * eps
    k = math.log(target) / math.log(q0)
    if k <= 1.0:
        return 0
    return math.ceil(math.log2(k))

def classify(c: float, p: float) -> str:
    q0 = c * p
    if q0 < 1.0:
        return "below threshold  -> logical error -> 0"
    if q0 == 1.0:
        return "at threshold     -> logical error frozen at 1/c"
    return "above threshold  -> logical error -> +inf"
